"""Human-owned HTTP acceptance; cumulative phases, never generated by the model."""
from pathlib import Path
import urllib.request, urllib.parse, urllib.error, subprocess, sys, os, tempfile, re
phase=int(sys.argv[1]); root=Path(__file__).resolve().parent.parent
with tempfile.TemporaryDirectory() as data:
    proc=subprocess.Popen([sys.executable,str(root/'src/server.py'),'0'],stdout=subprocess.PIPE,text=True,env={**os.environ,'URAL_DATA':data})
    try:
        port=proc.stdout.readline().strip(); assert port.isdigit(),port
        def get(path):return urllib.request.urlopen('http://127.0.0.1:'+port+path,timeout=10).read().decode()
        def check(page,words):
            text=get(page)
            for word in words:assert word.casefold() in text.casefold(),(page,word)
            assert 'lang="ru"' in text and '<main' in text and '<nav' in text,(page,'semantic structure')
            assert 'http://' not in text and 'https://' not in text,(page,'external resource')
            return text
        check('/', ['Уральская тропа','Конжаковский','/routes','/signup','/style.css','/assets/konzhak.jpg','alt='])
        css=get('/style.css');assert '@media' in css and 'focus' in css and len(css)>300
        if phase>=2:
            check('/routes',['Конжаковский','Таганай','Иремель','/trail'])
            check('/trail',['Конжаковский','Северный Урал','подготов','/signup'])
        def post(name='Анна',email='anna@example.org',route='konzhak'):
            req=urllib.request.Request('http://127.0.0.1:'+port+'/signup',data=urllib.parse.urlencode(dict(name=name,email=email,route=route)).encode(),headers={'Content-Type':'application/x-www-form-urlencoded'})
            try:return urllib.request.urlopen(req,timeout=10).status
            except urllib.error.HTTPError as e:return e.code
        if phase>=3:
            check('/signup',['<form','method="post"','action="/signup"','name="name"','name="email"','name="route"','<label','required','Демонстрацион'])
            assert post()==201
            for args in [dict(name=''),dict(email='bad'),dict(route='unknown')]:assert post(**args)==400,args
            assert len((Path(data)/'requests.jsonl').read_text().splitlines())==1
        if phase>=4:check('/about',['демонстрацион','Антонов','лиценз','данн','/assets/konzhak.jpg'])
        if phase>=5:
            for name in ['<script>alert(1)</script>','a'*101,'Ann\nOther']:
                assert post(name=name)==400,name
            assert post(email='a'*255+'@example.org')==400
            for path in ['/../README.md','/src/booking.py']:
                try:get(path);raise AssertionError('private file exposed')
                except urllib.error.HTTPError as e:assert e.code==404
        print('PASS cumulative phase',phase,'HTTP pages, application behavior and negative cases')
    finally:proc.terminate();proc.wait(timeout=5)
